sp_widget.client_script:
api.controller = function($location) {

    var c = this;

    // ==========================================
    // VARIABLES
    // ==========================================

    c.loading = true;
    c.documentFound = false;
    c.document = {};
    c.processing = false;

    c.showRejectionBox = false;
    c.rejectionReason = "";
    c.redirecting = false;


    // ==========================================
    // LOAD / REFRESH DOCUMENT
    // ==========================================

    c.loadDocument = function() {

        c.loading = true;

        var params = $location.search();

        var documentSysId =
            params.document_sys_id || "";

        if (!documentSysId) {

            c.loading = false;
            c.documentFound = false;

            return;
        }

        c.server.get({

            action: "get_document",

            document_sys_id: documentSysId

        }).then(function(response) {

            c.loading = false;

            if (response.data.success === true) {

                c.documentFound = true;
                c.document = response.data.document;

            } else {

                c.documentFound = false;

            }

        }, function() {

            c.loading = false;
            c.documentFound = false;

        });

    };


    // ==========================================
    // APPROVE DOCUMENT
    // ==========================================

    c.approveDocument = function() {

        var params = $location.search();

        var documentSysId =
            params.document_sys_id || "";

        if (!documentSysId) {

            alert("Document information is missing.");
            return;
        }

        c.processing = true;

        c.server.get({

            action: "update_status",

            document_sys_id: documentSysId,

            new_status: "approved"

        }).then(function(response) {

            c.processing = false;

            if (response.data.success === true) {

                c.showRejectionBox = false;
                c.rejectionReason = "";

                // Show Approved status
                c.loadDocument();

                // Enable redirect
                c.redirecting = true;

                // Go to Home after 3 seconds
                setTimeout(function() {

                    $location.search({
                        id: "claim_home"
                    });

                }, 3000);

            } else {

                alert(
                    response.data.message ||
                    "Unable to approve document."
                );

            }

        }, function() {

            c.processing = false;

            alert(
                "Unable to update document status."
            );

        });

    };


    // ==========================================
    // SHOW REJECTION BOX
    // ==========================================

    c.showRejectBox = function() {

        c.showRejectionBox = true;
        c.rejectionReason = "";

    };


    // ==========================================
    // CANCEL REJECTION
    // ==========================================

    c.cancelReject = function() {

        c.showRejectionBox = false;
        c.rejectionReason = "";

    };


    // ==========================================
    // CONFIRM REJECTION
    // ==========================================

    c.confirmReject = function() {

        var params = $location.search();

        var documentSysId =
            params.document_sys_id || "";

        if (!documentSysId) {

            alert("Document information is missing.");
            return;
        }

        if (!c.rejectionReason ||
            !c.rejectionReason.trim()) {

            alert("Please enter a rejection reason.");
            return;
        }

        c.processing = true;

        c.server.get({

            action: "update_status",

            document_sys_id: documentSysId,

            new_status: "rejected",

            rejection_reason:
                c.rejectionReason.trim()

        }).then(function(response) {

            c.processing = false;

            if (response.data.success === true) {

                c.showRejectionBox = false;

                // Show Rejected status
                c.loadDocument();

                // Enable redirect
                c.redirecting = true;

                // Go to Home after 3 seconds
                setTimeout(function() {

                    $location.search({
                        id: "claim_home"
                    });

                }, 3000);

            } else {

                alert(
                    response.data.message ||
                    "Unable to reject document."
                );

            }

        }, function() {

            c.processing = false;

            alert(
                "Unable to update document status."
            );

        });

    };


    // ==========================================
    // INITIAL LOAD
    // ==========================================

    c.loadDocument();

};

sp_widget.css:
.status-container {
    max-width: 900px;
    margin: 40px auto;
    padding: 20px;
}


/* ============================= */
/* HEADER */
/* ============================= */

.status-header {
    display: flex;
    align-items: center;
    gap: 18px;
    margin-bottom: 25px;
}

.status-icon {
    width: 58px;
    height: 58px;
    border-radius: 14px;
    background: #eaf3ff;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 28px;
}

.status-header h1 {
    margin: 0;
    font-size: 30px;
    color: #1f2937;
}

.status-header p {
    margin: 6px 0 0;
    color: #6b7280;
    font-size: 15px;
}


/* ============================= */
/* CARD */
/* ============================= */

.status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 30px;

    box-shadow:
        0 5px 20px rgba(0, 0, 0, 0.08);

    border: 1px solid #e5e7eb;
}

.status-card h2 {
    margin-top: 0;
    margin-bottom: 25px;

    color: #1f2937;
    font-size: 22px;
}


/* ============================= */
/* INFORMATION */
/* ============================= */

.info-row {
    display: flex;
    justify-content: space-between;
    align-items: center;

    padding: 17px 0;

    border-bottom: 1px solid #eeeeee;
}

.info-row span:first-child {
    color: #6b7280;
    font-size: 15px;
}

.info-row strong {
    color: #1f2937;
    font-size: 15px;
}


/* ============================= */
/* STATUS BADGE */
/* ============================= */

.status-badge {
    padding: 7px 15px;

    border-radius: 20px;

    font-size: 13px;
    font-weight: 600;
}

.status-badge.pending {
    background: #fff3cd;
    color: #856404;
}

.status-badge.approved {
    background: #d1e7dd;
    color: #0f5132;
}

.status-badge.rejected {
    background: #f8d7da;
    color: #842029;
}


/* ============================= */
/* STATUS MESSAGE */
/* ============================= */

.status-message {
    margin-top: 25px;

    padding: 15px;

    border-radius: 8px;

    background: #fff8e1;
    color: #795548;
}

.approved-message {
    background: #e8f5e9;
    color: #2e7d32;
}

.rejected-message {
    background: #ffebee;
    color: #c62828;
}


/* ============================= */
/* APPROVE / REJECT BUTTONS */
/* ============================= */

.validation-actions {
    display: flex;
    gap: 15px;

    margin-top: 25px;
}

.approve-btn,
.reject-btn {
    border: none;

    padding: 13px 24px;

    border-radius: 8px;

    font-size: 15px;
    font-weight: 600;

    cursor: pointer;

    transition: 0.2s;
}

.approve-btn {
    background: #198754;
    color: white;
}

.approve-btn:hover {
    background: #157347;
}

.reject-btn {
    background: #dc3545;
    color: white;
}

.reject-btn:hover {
    background: #bb2d3b;
}

.approve-btn:disabled,
.reject-btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* ============================= */
/* REJECTION BOX */
/* ============================= */

.reject-box {
    margin-top: 25px;

    padding: 20px;

    border: 1px solid #f1caca;

    border-radius: 10px;

    background: #fff8f8;
}

.reject-box h3 {
    margin-top: 0;
    margin-bottom: 8px;

    color: #b42318;

    font-size: 18px;
}

.reject-box p {
    margin-bottom: 15px;

    color: #666;

    font-size: 14px;
}


/* REJECTION TEXTAREA */

.rejection-input {
    width: 100%;

    min-height: 100px;

    padding: 12px;

    border: 1px solid #d5d5d5;

    border-radius: 7px;

    resize: vertical;

    font-size: 14px;

    box-sizing: border-box;
}

.rejection-input:focus {
    outline: none;

    border-color: #dc3545;
}


/* REJECTION BUTTONS */

.reject-box-actions {
    display: flex;

    justify-content: flex-end;

    gap: 12px;

    margin-top: 15px;
}

.cancel-reject-btn {
    padding: 10px 18px;

    border: 1px solid #999;

    background: white;

    color: #555;

    border-radius: 7px;

    cursor: pointer;
}

.cancel-reject-btn:hover {
    background: #f5f5f5;
}

.confirm-reject-btn {
    padding: 10px 18px;

    border: none;

    background: #dc3545;

    color: white;

    border-radius: 7px;

    cursor: pointer;

    font-weight: 600;
}

.confirm-reject-btn:hover {
    background: #bb2d3b;
}


/* ============================= */
/* REJECTION REASON */
/* ============================= */

.rejection-reason {
    margin-top: 12px;

    padding: 10px;

    background: #ffffff;

    border-radius: 6px;

    color: #7f1d1d;
}

.rejection-reason strong {
    margin-right: 5px;
}


/* ============================= */
/* PROCESSING */
/* ============================= */

.processing-message {
    margin-top: 20px;

    padding: 12px;

    background: #eef4ff;

    color: #2457a6;

    border-radius: 8px;

    text-align: center;
}


/* ============================= */
/* REFRESH BUTTON */
/* ============================= */

.refresh-btn {
    margin-top: 25px;

    padding: 11px 20px;

    border: 1px solid #2563eb;

    background: white;

    color: #2563eb;

    border-radius: 8px;

    font-weight: 600;

    cursor: pointer;
}

.refresh-btn:hover {
    background: #eff6ff;
}

.refresh-btn:disabled {
    opacity: 0.6;

    cursor: not-allowed;
}


/* ============================= */
/* LOADING */
/* ============================= */

.loading {
    text-align: center;

    padding: 30px;

    color: #6b7280;
}


/* ============================= */
/* ERROR */
/* ============================= */

.error-card {
    text-align: center;
}

.error-card h2 {
    color: #dc3545;
}


/* ============================= */
/* MOBILE */
/* ============================= */

@media (max-width: 600px) {

    .status-container {
        margin: 20px auto;
        padding: 12px;
    }

    .status-card {
        padding: 20px;
    }

    .info-row {
        flex-direction: column;
        align-items: flex-start;

        gap: 8px;
    }

    .validation-actions {
        flex-direction: column;
    }

    .approve-btn,
    .reject-btn {
        width: 100%;
    }

    .reject-box-actions {
        flex-direction: column;
    }

    .cancel-reject-btn,
    .confirm-reject-btn {
        width: 100%;
    }

}

sp_widget.script:
(function() {
    data.is_admin = gs.hasRole('admin') || gs.hasRole('x_snc_insurance_0.claim admin');

    data.success = false;

    data.document = {};

    data.message = "";


    // ==========================================
    // CHECK INPUT
    // ==========================================

    if (!input) {

        return;

    }


    // ==========================================
    // GET DOCUMENT
    // ==========================================

    if (input.action == "get_document") {


        var documentSysId =
            String(
                input.document_sys_id || ""
            );


        if (!documentSysId) {

            data.message =
                "Document information is missing.";

            return;

        }


        // Find document

        var document =
            new GlideRecord(
                "x_snc_insurance_0_claim_document"
            );


        if (!document.get(documentSysId)) {

            data.message =
                "Document not found.";

            return;

        }


        // ======================================
        // GET CLAIM NUMBER
        // ======================================

        var claimNumber = "";


        var claimSysId =
            document.getValue("claim");


        if (claimSysId) {


            var claim =
                new GlideRecord(
                    "x_snc_insurance_0_claim"
                );


            if (claim.get(claimSysId)) {

                claimNumber =
                    claim.getValue(
                        "claim_number"
                    );

            }

        }


        // ======================================
        // RETURN DOCUMENT
        // ======================================

        data.success = true;


        data.document = {

            claim_number:
                claimNumber,


            document_name:
                document.getValue(
                    "document_name"
                ) || "",


            document_type:
                document.getDisplayValue(
                    "document_type"
                ) || "",


            validation_status:
                document.getDisplayValue(
                    "document_validation_status"
                ) || "Pending",


            rejection_reason:
                document.getValue(
                    "rejection_reason"
                ) || ""

        };


        return;

    }



    // ==========================================
    // UPDATE DOCUMENT STATUS
    // ==========================================

    if (input.action == "update_status") {


        var updateDocumentSysId =
            String(
                input.document_sys_id || ""
            );


        var newStatus =
            String(
                input.new_status || ""
            );


        var rejectionReason =
            String(
                input.rejection_reason || ""
            );


        // ======================================
        // CHECK DOCUMENT ID
        // ======================================

        if (!updateDocumentSysId) {

            data.message =
                "Document information is missing.";

            return;

        }


        // ======================================
        // CHECK STATUS
        // ======================================

        if (newStatus != "approved" &&
            newStatus != "rejected") {

            data.message =
                "Invalid document status.";

            return;

        }


        // ======================================
        // FIND DOCUMENT
        // ======================================

        var documentToUpdate =
            new GlideRecord(
                "x_snc_insurance_0_claim_document"
            );


        if (!documentToUpdate.get(
                updateDocumentSysId
            )) {

            data.message =
                "Document was not found.";

            return;

        }


        // ======================================
        // UPDATE STATUS
        // ======================================

        documentToUpdate.setValue(
            "document_validation_status",
            newStatus
        );


        // ======================================
        // REJECTION REASON
        // ======================================

        if (newStatus == "rejected") {


            if (!rejectionReason ||
                !rejectionReason.trim()) {

                data.message =
                    "Please enter a rejection reason.";

                return;

            }


            documentToUpdate.setValue(
                "rejection_reason",
                rejectionReason.trim()
            );


        } else {


            // If approved,
            // remove any old rejection reason

            documentToUpdate.setValue(
                "rejection_reason",
                ""
            );

        }


        // ======================================
        // SAVE RECORD
        // ======================================

        var updateResult =
            documentToUpdate.update();


        if (!updateResult) {

            data.message =
                "Unable to update document status.";

            return;

        }


        // ======================================
        // SUCCESS
        // ======================================

        data.success = true;

        data.message =
            "Document status updated successfully.";

        return;

    }


})();
